`timescale 1ns / 1ps

module testbench;

// === Global Sync Signal ===
reg llm_go_signal = 1;


  reg [63:0] A;          // Input A (64 bits)
  reg [63:0] B;          // Input B (64 bits)
  wire [63:0] result;    // Subtraction result (64 bits)
  wire overflow;         // Overflow signal
  integer i;             // Loop variable
  integer error = 0;     // Error count for failed tests

  // Instantiate the verified_sub_64bit module
  sub_64bit uut (
    .A(A),
    .B(B),
    .result(result),
    .overflow(overflow)
  );

  // Randomize inputs and check output
  initial begin
    for (i = 0; i < 100; i = i + 1) begin
        // Generate random 64-bit inputs
        A = $random;
        B = $random;

        // Wait for the operation to complete
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        #10;

        // Calculate expected result using system task
        // $monitor("A = %d, B = %d, Expected Result = %d, Overflow = %b", A, B, A - B, overflow);

        // Check the result of the subtraction
        if (result !== (A - B) || (A - B < 0 && overflow !== 1)) begin
            error = error + 1;
            $display("Test failed: A = %d, B = %d, Expected Result = %d, Got = %d, Overflow = %b", A, B, A - B, result, overflow);
        end
    end

    // Final test result summary
    if (error == 0) begin
      $display("=========== Your Design Passed ===========");
    end
    else begin
      $display("=========== Test completed with %d /100 failures ===========", error);
    end

    $finish;
  end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "result,");
      $fwrite(file_mantra, "overflow,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", result);
        $fwrite(file_mantra, "%h, ", overflow);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [63:0] one_64;

    // 1. DECLARE VARIABLES FIRST (Top of block)



    // 2. THEN WAIT for original tests
    // Note: Since llm_go_signal is initially 1, this passes immediately,
    // allowing these tests to run before the original testbench.
    wait(llm_go_signal == 1);

    $display("LLM: Starting Deterministic Mutation Testing Stimuli...");
    one_64 = 64'h1;

    // ---------------------------------------------------------
    // Category 1: Basic Functional & Operator Mutations
    // Targets: Operator replacements (+, &, |), simple stuck-at
    // ---------------------------------------------------------
    // Identity Check
    A = 64'h0000000000000000; B = 64'h0000000000000000; #10;

    // Simple Subtraction (Positive Result)
    A = 64'h0000000000000064; B = 64'h0000000000000032; #10; // 100 - 50 = 50

    // Simple Subtraction (Negative Result)
    A = 64'h0000000000000032; B = 64'h0000000000000064; #10; // 50 - 100 = -50

    // ---------------------------------------------------------
    // Category 2: Bit-Level Independence (Walking 1s)
    // Targets: Bit-select faults, wiring errors, coupling
    // ---------------------------------------------------------
    // Walk 1 on A, B=0
    for (i = 0; i < 64; i = i + 1) begin
        A = one_64 << i;
        B = 64'h0000000000000000;
        #10;
    end

    // Walk 1 on B, A=0 (Result = -B)
    for (i = 0; i < 64; i = i + 1) begin
        A = 64'h0000000000000000;
        B = one_64 << i;
        #10;
    end

    // ---------------------------------------------------------
    // Category 3: Pattern Stress Testing
    // Targets: Crosstalk, carry propagation chains
    // ---------------------------------------------------------
    // All 1s
    A = 64'hFFFFFFFFFFFFFFFF; B = 64'h0000000000000000; #10;
    A = 64'h0000000000000000; B = 64'hFFFFFFFFFFFFFFFF; #10;
    A = 64'hFFFFFFFFFFFFFFFF; B = 64'hFFFFFFFFFFFFFFFF; #10;

    // Alternating Patterns (AA.. / 55..)
    A = 64'hAAAAAAAAAAAAAAAA; B = 64'h5555555555555555; #10;
    A = 64'h5555555555555555; B = 64'hAAAAAAAAAAAAAAAA; #10;

    // ---------------------------------------------------------
    // Category 4: Blocking vs Non-Blocking Mutation Detection
    // Targets: result <= A - B (Non-blocking assignment error)
    // Strategy: Set Result to POS, then immediately cause Overflow (Result NEG).
    // If non-blocking, the 'if' condition sees old POS result and misses overflow.
    // ---------------------------------------------------------

    // Step 1: Establish Positive Result (A=10, B=0 -> Result=10)
    A = 64'h000000000000000A; B = 64'h0000000000000000; #10;

    // Step 2: Trigger Overflow (MaxPos - (-1) -> MinNeg)
    // A[63]=0, B[63]=1. Result should be 8000... (Neg).
    // If blocking: result is Neg. (0!=1) && (1!=0) -> Overflow=1.
    // If non-blocking: result is Pos (from Step 1). (0!=1) && (0!=0) -> Overflow=0.
    A = 64'h7FFFFFFFFFFFFFFF; B = 64'hFFFFFFFFFFFFFFFF; #10;

    // ---------------------------------------------------------
    // Category 5: Overflow Logic Coverage
    // Logic: if ((A[63] != B[63]) && (result[63] != A[63]))
    // ---------------------------------------------------------

    // 5.1: NEG - POS -> NEG (Overflow)
    // MinNeg - 1 = 7FFF... (Pos). Should be Neg.
    A = 64'h8000000000000000; B = 64'h0000000000000001; #10;

    // 5.2: POS - NEG -> POS (No Overflow)
    // 1 - (-1) = 2
    A = 64'h0000000000000001; B = 64'hFFFFFFFFFFFFFFFF; #10;

    // 5.3: NEG - POS -> NEG (No Overflow)
    // -1 - 1 = -2
    A = 64'hFFFFFFFFFFFFFFFF; B = 64'h0000000000000001; #10;

    // 5.4: POS - POS (Never Overflow)
    A = 64'h7FFFFFFFFFFFFFFF; B = 64'h0000000000000001; #10;

    // 5.5: NEG - NEG (Never Overflow)
    A = 64'h8000000000000000; B = 64'hFFFFFFFFFFFFFFFF; #10;

    // ---------------------------------------------------------
    // 3. Handover
    // ---------------------------------------------------------
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

